// Bronwyn's letterheads, taken from her 2026 Word masters
// (_contract_templates/2026-final/*.docx), so logo, strapline, "Initial here"
// box, address and directors line are exactly hers.
//
// Her masters carry two letterheads:
//   "properties" — DREAM PROPERTIES logo: the freehold-house and land
//                  agreements, mandates, movables and addenda.
//   "knysna"     — DREAM KNYSNA logo (as in "Dream Properties Letterhead &
//                  Page Numbers.docx"): the sectional-title agreement.
//
// Each image is a full-page-width strip (A4, 595.28 pt) cut from a 300 dpi
// render of the master; `top`/`bottom` are the strip's position on the page
// in points, so it is placed exactly where Word puts it. "First" is page 1
// (Word's different-first-page header/footer).
// Generated — do not edit by hand.

export type LetterheadPart = { src: string; top: number; bottom: number };
export type Letterhead = { headerFirst: LetterheadPart; header: LetterheadPart; footerFirst: LetterheadPart; footer: LetterheadPart };

export const LETTERHEADS: Record<"properties" | "knysna", Letterhead> = {
  properties: {
    headerFirst: { top: 0, bottom: 100, src: "data:image/jpeg;base64," },
    header: { top: 0, bottom: 62, src: "data:image/jpeg;base64," },
    footerFirst: { top: 705, bottom: 800, src: "data:image/jpeg;base64," },
    footer: { top: 735, bottom: 800, src: "data:image/jpeg;base64," },
  },
  knysna: {
    headerFirst: { top: 0, bottom: 124, src: "data:image/jpeg;base64," },
    header: { top: 0, bottom: 80, src: "data:image/jpeg;base64," },
    footerFirst: { top: 708, bottom: 800, src: "data:image/jpeg;base64," },
    footer: { top: 727.3, bottom: 800, src: "data:image/jpeg;base64," },
  },
};
